const applyBodies = (articles, bodies) => articles.map((item, articleIndex) => ({
  ...item,
  sections: item.sections.map(([heading], sectionIndex) => [heading, bodies[articleIndex][sectionIndex]]),
}));

export const localizedPriorityArticlesTwo = { de, es, fr: applyBodies(fr, frBodies), it: applyBodies(it, itBodies) };
